function vectorFor(n){
  const raw=rawVector(n),mode=$("#heightMode").value;
  let {x,y,z}=raw;
  const mag=Math.hypot(x,y,z)||1;
  if(mode==="log"){
    const target=Math.log(Math.max(n,1));
    x=x/mag*target;y=y/mag*target;z=z/mag*target;
  }else if(mode==="omega"){
    const target=bigOmega(raw.f);
    x=x/mag*target;y=y/mag*target;z=z/mag*target;
  }
  return {x,y,z,f:raw.f};
}
function drawFloorGrid(ctx,w,h){
  const rings=[1.5,3,4.5,6];
  ctx.save();ctx.globalAlpha=.18;ctx.strokeStyle="#7f8ea3";ctx.lineWidth=1;
  rings.forEach(r=>{
    const pts=[];
    for(let i=0;i<=72;i++){
      const a=i/72*Math.PI*2;
      pts.push(project3({x:r*Math.cos(a),y:r*Math.sin(a),z:0},w,h));
    }
    ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();
  });
  ctx.restore();
}
function renderPVG(){
  const c=$("#pvgCanvas"),ctx=c.getContext("2d"),{w,h,dpr}=resizeCanvas(c);
  ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);
  ctx.fillStyle=getComputedStyle(document.documentElement).getPropertyValue("--panel2");ctx.fillRect(0,0,w,h);
  const maxN=Number($("#maxN").value),windowY=Number($("#pvgWindow").value);$("#maxNVal").textContent=maxN;
  const cap=Number($("#axisLimit").value),drawnPrimes=primesUpTo(cap===0?maxN:Math.min(maxN,cap));
  $("#axisLegend").innerHTML=drawnPrimes.map(p=>`<div class="axisChip"><span class="dot" style="background:${primeColor(p)}"></span>×${p}</div>`).join("")+`<div class="axisChip muted">${drawnPrimes.length} محورًا مرسومًا من ${primesUpTo(maxN).length} محورًا فعّالًا في المجال</div>`+(windowY?`<div class="axisChip"><span class="dot" style="background:#25b77a"></span>نافذة p≤${windowY}: الأعداد الملساء كاملة الوضوح، والباقي يُبهت بقدر الفقد</div>`:"");
  drawFloorGrid(ctx,w,h);

  const origin=project3({x:0,y:0,z:0},w,h);
  ctx.lineWidth=3;
  drawnPrimes.forEach(p=>{
    const d=primeDir(p),len=6.2;
    const end=project3({x:d.x*len,y:d.y*len,z:d.z*len},w,h);
    ctx.strokeStyle=primeColor(p);ctx.globalAlpha=.92;
    ctx.beginPath();ctx.moveTo(origin.x,origin.y);ctx.lineTo(end.x,end.y);ctx.stroke();
    if($("#labelMode").value!=="none"){
      ctx.fillStyle=primeColor(p);ctx.font="17px Segoe UI";
      ctx.fillText(`×${p}`,end.x+6,end.y-3);
    }
  });

  const pts=[];
  for(let n=1;n<=maxN;n++){
    const v=vectorFor(n),pr=project3(v,w,h),win=windowY?projectionStats(v.f,n,windowY):null;
    pts.push({n,f:v.f,win,...pr});
  }
  pts.sort((a,b)=>a.depth-b.depth);

  for(const p of pts){
    const keys=Object.keys(p.f).map(Number),isPrime=keys.length===1&&p.f[keys[0]]===1,isPP=keys.length===1;
    let color="rgba(190,200,215,.74)",r=2.2*Math.max(.7,p.perspective);
    if(isPP){color=primeColor(keys[0]);r=(isPrime?5:4)*Math.max(.72,p.perspective)}
    if(p.n===pvgState.selected){
      ctx.beginPath();ctx.arc(p.x,p.y,12*Math.max(.75,p.perspective),0,Math.PI*2);
      ctx.strokeStyle="#d6a51d";ctx.lineWidth=5;ctx.stroke();r=7*Math.max(.75,p.perspective);
    }
    ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);
    ctx.fillStyle=color;const windowAlpha=!p.win?1:(p.win.smooth?1:.12+.55*p.win.keptRatio);ctx.globalAlpha=(isPP?1:.75)*windowAlpha;ctx.fill();
    if($("#labelMode").value==="primepowers"&&isPP&&p.n>1){
      ctx.fillStyle=color;ctx.font="12px Segoe UI";ctx.fillText(String(p.n),p.x+5,p.y-5);
    }
  }
  ctx.globalAlpha=1;ctx.beginPath();ctx.arc(origin.x,origin.y,7,0,Math.PI*2);ctx.fillStyle="#f5f7fb";ctx.fill();
  pvgState.points=pts;
  if(!pvgState.hover){
    $("#pvgHover").textContent=`اسحب للتدوير · Shift+سحب للتحريك · yaw ${(pvgState.yaw*180/Math.PI).toFixed(0)}° · pitch ${(pvgState.pitch*180/Math.PI).toFixed(0)}°`;
  }
}
function pvgDetail(n){
  const f=factor(n),support=Object.keys(f).map(Number),shape=shapeData(f,n),S=entropyOfShape(shape),rad=radFromFactor(f),windowY=Number($("#pvgWindow").value),win=windowY?projectionStats(f,n,windowY):null;
  const shapeHtml=shape.length?shape.map(x=>`<div class="shapeRow"><b>${x.p}</b><div class="shapeTrack"><div class="shapeFill" style="width:${(x.share*100).toFixed(2)}%;background:${primeColor(x.p)}"></div></div><span>${(x.share*100).toFixed(1)}%</span></div>`).join(""):`<span class="muted">لا شكل شعاعي للعدد 1.</span>`;
  $("#pvgDetail").innerHTML=`<div class="kind">PVG HIGH-DIMENSIONAL OBJECT · 3D PROJECTION</div><h3>n = ${n}</h3>
  <div class="badges"><span class="badge">ω=${omega(f)}</span><span class="badge">Ω=${bigOmega(f)}</span><span class="badge">P⁺=${maxPrime(f)}</span><span class="badge">H=log n=${Math.log(n).toFixed(4)}</span><span class="badge">S=${S.toFixed(4)}</span><span class="badge">e^S=${Math.exp(S).toFixed(3)}</span></div>
  <div class="block"><h4>التحليل</h4><p>${factText(f)}</p></div>
  <div class="block"><h4>متجه التقييمات</h4><p>${support.length?support.map(p=>`ν_${p}=${f[p]}`).join("، "):"المتجه الصفري"}</p></div>
  <div class="block"><h4>الدعم والارتفاع</h4><p>rad(n)=${rad} · log rad(n)=${Math.log(rad).toFixed(4)} · أعلى أس=${maxExponent(f)} · كتلة التكرار=${(Math.log(n)-Math.log(rad)).toFixed(4)}</p></div>
  <div class="block"><h4>صندوق القواسم</h4><p>0≤uₚ≤νₚ(n) على كل محور في الدعم، وعدد نقاط الصندوق τ(n)=${tauFromFactor(f)}.</p></div>
  <div class="block"><h4>فصل الحجم عن الشكل</h4><div class="shapeBars">${shapeHtml}</div></div>
  ${win?`<div class="block"><h4>نافذة p≤${windowY}</h4><p class="windowVector">Πᵧν(n)=${valuationText(win.keptFactor)}<br>tailᵧν(n)=${valuationText(win.tailFactor)}<br>Tᵧ=${win.tailH.toFixed(6)} · retained=${(win.keptRatio*100).toFixed(2)}%</p><span class="windowBadge ${win.smooth?'good':'loss'}">${win.smooth?'y-smooth: فقد صفري':'فقد غير صفري'}</span></div>`:``}
  <div class="block"><h4>حد الاستنتاج</h4><p>اتجاهات العرض الثلاثية إسقاط اختياري لفضاء عالي الأبعاد. القيم H وω وΩ وσ وTᵧ معرفة بدقة؛ أما الرسم ومقاييس الشكل فلا يثبتان متوسطًا أو إلغاءً أو توزيعًا دون مبرهنة مستقلة.</p></div>`;
}
function animationLoop(){
  if(!pvgState.auto){pvgState.raf=null;return}
  pvgState.yaw+=.004;
  renderPVG();
  pvgState.raf=requestAnimationFrame(animationLoop);
}
function initPVG(){
  $("#axisLegend").innerHTML="";
  ["#maxN","#heightMode","#labelMode","#axisLimit","#pvgWindow"].forEach(id=>$(id).addEventListener(id==="#maxN"?"input":"change",renderPVG));
  $("#autoRotate").onclick=()=>{
    pvgState.auto=!pvgState.auto;
    $("#autoRotate").textContent=pvgState.auto?"إيقاف الدوران":"تشغيل الدوران";
    if(pvgState.auto&&!pvgState.raf)pvgState.raf=requestAnimationFrame(animationLoop);
  };
  $("#resetPVG").onclick=()=>{
    if(pvgState.raf)cancelAnimationFrame(pvgState.raf);
    pvgState={selected:60,hover:null,zoom:1,panX:0,panY:0,yaw:-.42,pitch:.48,drag:null,points:[],auto:false,raf:null,moved:false};
    $("#autoRotate").textContent="تشغيل الدوران";
    $("#maxN").value=251;$("#heightMode").value="log";$("#labelMode").value="axes";$("#pvgWindow").value="0";
    pvgDetail(60);renderPVG();
  };
  const c=$("#pvgCanvas");
  c.addEventListener("contextmenu",e=>e.preventDefault());
  c.addEventListener("mousemove",e=>{
    if(pvgState.drag)return;
    const r=c.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;
    let best=null,bd=12;
    for(const p of pvgState.points){const d=Math.hypot(x-p.x,y-p.y);if(d<bd){bd=d;best=p}}
    if(best){
      $("#pvgHover").textContent=`n=${best.n} · ${factText(best.f)} · ω=${omega(best.f)} · Ω=${bigOmega(best.f)}`+(best.win?` · retained=${(best.win.keptRatio*100).toFixed(1)}%${best.win.smooth?" · smooth":""}`:"");
      pvgState.hover=best.n;
    }else{
      pvgState.hover=null;
      $("#pvgHover").textContent=`اسحب للتدوير · Shift+سحب للتحريك · yaw ${(pvgState.yaw*180/Math.PI).toFixed(0)}° · pitch ${(pvgState.pitch*180/Math.PI).toFixed(0)}°`;
    }
  });
  c.addEventListener("click",()=>{
    if(!pvgState.moved&&pvgState.hover){
      pvgState.selected=pvgState.hover;pvgDetail(pvgState.selected);renderPVG();
    }
    pvgState.moved=false;
  });
  c.addEventListener("wheel",e=>{
    e.preventDefault();
    pvgState.zoom=Math.max(.38,Math.min(2.8,pvgState.zoom*(e.deltaY<0?1.08:.92)));
    renderPVG();
  },{passive:false});
  c.addEventListener("pointerdown",e=>{
    const pan=e.shiftKey||e.button===1||e.button===2;
    pvgState.drag={
      mode:pan?"pan":"orbit",x:e.clientX,y:e.clientY,
      yaw:pvgState.yaw,pitch:pvgState.pitch,px:pvgState.panX,py:pvgState.panY
    };
    pvgState.moved=false;c.setPointerCapture(e.pointerId);
  });
  c.addEventListener("pointermove",e=>{
    if(!pvgState.drag)return;
    const dx=e.clientX-pvgState.drag.x,dy=e.clientY-pvgState.drag.y;
    if(Math.hypot(dx,dy)>3)pvgState.moved=true;
    if(pvgState.drag.mode==="orbit"){
      pvgState.yaw=pvgState.drag.yaw+dx*.008;
      pvgState.pitch=Math.max(-1.42,Math.min(1.42,pvgState.drag.pitch+dy*.008));
    }else{
      pvgState.panX=pvgState.drag.px+dx;pvgState.panY=pvgState.drag.py+dy;
    }
    renderPVG();
  });
  c.addEventListener("pointerup",()=>pvgState.drag=null);
  c.addEventListener("pointercancel",()=>pvgState.drag=null);
  pvgDetail(60);renderPVG();
}

