  const sum=m+n,fSum=factor(sum),fake={};for(const p of new Set([...Object.keys(fm),...Object.keys(fn)])){fake[p]=(fm[p]||0)+(fn[p]||0)}
  const same=JSON.stringify(fSum)===JSON.stringify(fake);
