function saddlePointApprox(x,ps){const L=Math.log(x);if(!ps.length)return {alpha:0,zeta:1,phi2:0,approx:1,mean:0,berry:0,skew:0,maxShare:0,effectiveDim:0,components:[]};const stats=(a,full=false)=>{let mean=0,logZ=0,phi2=0,phi3=0,abs3=0,varSquares=0,maxVar=0;const components=[];for(const p of ps){const lp=Math.log(p),r=Math.exp(-a*lp),q=Math.max(1e-300,1-r),mu=r/q,v=r/(q*q),vp=lp*lp*v,c3=r*(1+r)/(q*q*q);mean+=lp*mu;logZ-=Math.log(q);phi2+=vp;phi3+=lp*lp*lp*c3;varSquares+=vp*vp;maxVar=Math.max(maxVar,vp);if(full){const ap=lp*lp*lp*geometricAbsThird(r);abs3+=ap;components.push({p,r,mean:mu,variance:vp,abs3:ap})}}return {mean,logZ,phi2,phi3,abs3,varSquares,maxVar,components}};let lo=1e-10,hi=1;while(stats(hi).mean>L&&hi<128)hi*=2;for(let i=0;i<110;i++){const mid=(lo+hi)/2;if(stats(mid).mean>L)lo=mid;else hi=mid}const alpha=(lo+hi)/2,s=stats(alpha,true),scale=Math.pow(s.phi2,1.5),logA=alpha*L+s.logZ-Math.log(alpha)-.5*(Math.log(2*Math.PI)+Math.log(s.phi2));return {alpha,zeta:Math.exp(s.logZ),phi2:s.phi2,approx:Math.exp(logA),mean:s.mean,berry:scale?s.abs3/scale:NaN,skew:scale?s.phi3/scale:NaN,maxShare:s.phi2?s.maxVar/s.phi2:NaN,effectiveDim:s.varSquares?s.phi2*s.phi2/s.varSquares:NaN,components:s.components}}
function generateSmoothData(limit,ps,budget){const values=[],vectors=[],e=Array(ps.length).fill(0),state={nodes:0,aborted:false};function rec(i,current){if(state.aborted)return;state.nodes++;if(state.nodes>budget){state.aborted=true;return}if(i===ps.length){values.push(current);if(vectors.length<50000)vectors.push({n:current,e:[...e]});return}const p=ps[i];let v=current,k=0;while(v<=limit){e[i]=k;rec(i+1,v);if(state.aborted)return;if(v>Math.floor(limit/p))break;v*=p;k++}e[i]=0}rec(0,1);if(!state.aborted){values.sort((a,b)=>a-b);vectors.sort((a,b)=>a.n-b.n)}return {values,vectors,nodes:state.nodes,aborted:state.aborted}}
