function formatNum(x,d=6){if(!Number.isFinite(x))return '—';if(Math.abs(x)>=1e7||Math.abs(x)<1e-4&&x!==0)return x.toExponential(4);return x.toLocaleString('en-US',{maximumFractionDigits:d})}
function relativeError(a,truth){return truth?Math.abs(a-truth)/truth:NaN}
const DICKMAN_STEP=.0002,DICKMAN_ONE=Math.round(1/DICKMAN_STEP),dickmanCache=[...Array(DICKMAN_ONE+1)].map(()=>1);
function ensureDickman(maxU){const target=Math.max(DICKMAN_ONE,Math.ceil(maxU/DICKMAN_STEP));for(let i=dickmanCache.length;i<=target;i++){const u=i*DICKMAN_STEP,prevU=(i-1)*DICKMAN_STEP;const lagNow=dickmanCache[i-DICKMAN_ONE]??0,lagPrev=dickmanCache[Math.max(0,i-1-DICKMAN_ONE)]??1;const dNow=-lagNow/u,dPrev=-lagPrev/Math.max(1,prevU);dickmanCache[i]=Math.max(0,dickmanCache[i-1]+.5*DICKMAN_STEP*(dPrev+dNow))}}
