function median(a){if(!a.length)return NaN;const b=[...a].sort((x,y)=>x-y),m=b.length>>1;return b.length%2?b[m]:(b[m-1]+b[m])/2}
function geometricPoints(maxX,count=10){const minX=10,out=[];for(let i=0;i<count;i++){const z=Math.max(2,Math.round(Math.exp(Math.log(minX)+(Math.log(maxX)-Math.log(minX))*i/(count-1))));if(!out.includes(z))out.push(z)}return out}
function pearson(xs,ys){const n=Math.min(xs.length,ys.length);if(n<2)return NaN;const mx=xs.reduce((a,b)=>a+b,0)/n,my=ys.reduce((a,b)=>a+b,0)/n;let num=0,dx=0,dy=0;for(let i=0;i<n;i++){const a=xs[i]-mx,b=ys[i]-my;num+=a*b;dx+=a*a;dy+=b*b}return dx&&dy?num/Math.sqrt(dx*dy):NaN}
function ranks(a){const idx=a.map((v,i)=>({v,i})).sort((x,y)=>x.v-y.v),r=Array(a.length);for(let i=0;i<idx.length;){let j=i+1;while(j<idx.length&&idx[j].v===idx[i].v)j++;const rank=(i+j-1)/2+1;for(let k=i;k<j;k++)r[idx[k].i]=rank;i=j}return r}
