function drawErrorHeatmap(grid){const c=$("#errorHeatmap"),ctx=c.getContext('2d'),{w,h,dpr}=resizeCanvas(c);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--panel2');ctx.fillRect(0,0,w,h);const mode=$("#errorMode").value,pad={l:68,r:18,t:42,b:55},rows=grid.rows,cols=grid.xs,cw=(w-pad.l-pad.r)/cols.length,ch=(h-pad.t-pad.b)/rows.length;errorHeatState.cells=[];ctx.font='11px Segoe UI';ctx.textAlign='center';ctx.textBaseline='middle';cols.forEach((x,j)=>{ctx.fillStyle='#9aa8ba';ctx.save();ctx.translate(pad.l+(j+.5)*cw,h-pad.b+24);ctx.rotate(-.45);ctx.fillText(x.toLocaleString('en-US'),0,0);ctx.restore()});rows.forEach((r,i)=>{ctx.fillStyle='#dbeafe';ctx.fillText(`y=${r.y}`,pad.l-31,pad.t+(i+.5)*ch);if(r.aborted){ctx.fillStyle='rgba(245,165,36,.25)';ctx.fillRect(pad.l,pad.t+i*ch,cw*cols.length,ch);return}r.cells.forEach((cell,j)=>{const x0=pad.l+j*cw,y0=pad.t+i*ch,key=mode==='winner'?cell.winner:mode,err=cell.errors[key];ctx.fillStyle=mode==='winner'?ERROR_METHODS[key].color:heatColor(err);ctx.globalAlpha=mode==='winner'?.32+.62/(1+4*err):.82;ctx.fillRect(x0+1,y0+1,cw-2,ch-2);ctx.globalAlpha=1;ctx.strokeStyle='rgba(255,255,255,.07)';ctx.strokeRect(x0+.5,y0+.5,cw-1,ch-1);ctx.fillStyle='#fff';ctx.font=`${Math.max(9,Math.min(12,ch*.28))}px Segoe UI`;ctx.fillText(mode==='winner'?ERROR_METHODS[key].short:`${(100*err).toFixed(err<.1?1:0)}%`,x0+cw/2,y0+ch/2);errorHeatState.cells.push({x0,y0,w:cw,h:ch,cell})})});ctx.textAlign='left';ctx.fillStyle='#9aa8ba';ctx.font='11px Segoe UI';ctx.fillText(mode==='winner'?'S=السـرج · D=ديكمان · V=الحجم؛ شفافية أعلى تعني خطأ أقل':'اللون الأخضر خطأ أقل، والأحمر خطأ أكبر؛ النسبة داخل الخلية هي الخطأ النسبي',pad.l,19)}
function renderErrorGrid(){if(!lastErrorGrid)return;const g=lastErrorGrid,stats=Object.keys(ERROR_METHODS).map(k=>[k,methodStats(g,k)]);$("#errorStatus").className='errorStatus'+(g.rows.some(r=>r.aborted)?' warn':'');$("#errorStatus").textContent=`${g.rows.filter(r=>!r.aborted).length}/${g.rows.length} صفوف مكتملة · ${g.xs.length} قيم x · ${(g.elapsed_ms||0).toFixed(1)} ms`+(g.rows.some(r=>r.aborted)?' · بعض الصفوف تجاوزت الميزانية ولم تدخل الإحصاء.':'');$("#errorSummary").innerHTML=stats.map(([k,z])=>`<div class="errorMethod"><b style="color:${ERROR_METHODS[k].color}">${ERROR_METHODS[k].label}</b><span>الوسيط ${(100*z.median).toFixed(2)}% · المتوسط ${(100*z.mean).toFixed(2)}% · الأسوأ ${(100*z.max).toFixed(2)}% · فاز ${z.wins} مرة</span></div>`).join('');drawErrorHeatmap(g);const cells=g.rows.flatMap(r=>r.cells),hard=[...cells].sort((a,b)=>Math.min(...Object.values(b.errors))-Math.min(...Object.values(a.errors))).slice(0,8);$("#errorReport").innerHTML=`<table class="errorReportTable"><thead><tr><th>x</th><th>y</th><th>u</th><th>الأفضل</th><th>خطأ الأفضل</th><th>السـرج</th><th>ديكمان</th><th>الحجم</th></tr></thead><tbody>${hard.map(c=>`<tr><td>${c.x.toLocaleString('en-US')}</td><td>${c.y}</td><td>${c.u.toFixed(2)}</td><td class="winner${ERROR_METHODS[c.winner].short}">${ERROR_METHODS[c.winner].label}</td><td>${(100*c.errors[c.winner]).toFixed(2)}%</td><td>${(100*c.errors.saddle).toFixed(2)}%</td><td>${(100*c.errors.dickman).toFixed(2)}%</td><td>${(100*c.errors.volume).toFixed(2)}%</td></tr>`).join('')}</tbody></table><div class="miniNote">الجدول يعرض أصعب الخلايا حتى بعد اختيار أفضل الطرق الثلاث. لا يجوز تحويل الأداء التجريبي إلى حد خطأ نظري.</div>`;renderCertificateLab()}
