function renderCertificateLab(){if(!lastErrorGrid)return;const cells=lastErrorGrid.rows.flatMap(r=>r.cells);if(!cells.length)return;const berry=cells.map(c=>c.diagnostics.berry),err=cells.map(c=>c.errors.saddle),skew=cells.map(c=>c.diagnostics.skew),share=cells.map(c=>c.diagnostics.maxShare),neff=cells.map(c=>c.diagnostics.effectiveDim),rp=pearson(berry,err),rs=spearman(berry,err),summary=[['Pearson(𝓑,error)',rp.toFixed(4)],['Spearman(𝓑,error)',rs.toFixed(4)],['𝓑 median',median(berry).toFixed(4)],['max-share median',median(share).toFixed(4)],['n_eff median',median(neff).toFixed(3)],['الحالات',cells.length]];$("#certificateSummary").innerHTML=summary.map(([a,b])=>`<div class="metric"><b>${b}</b><span>${a}</span></div>`).join('');drawCertificateScatter(cells);const bins=calibrationBins(cells),regimes=['balanced','transition','axis'].map(k=>{const a=cells.filter(c=>c.diagnostics.regime===k),e=a.map(c=>c.errors.saddle);return {k,n:a.length,median:median(e),mean:e.reduce((x,y)=>x+y,0)/(e.length||1)}});$("#certificateReport").innerHTML=`<h3>معايرة تجريبية</h3><table class="certificateTable"><thead><tr><th>مجال 𝓑</th><th>n</th><th>وسيط الخطأ</th><th>متوسطه</th></tr></thead><tbody>${bins.map(b=>`<tr><td>${b.lo.toFixed(3)}–${b.hi.toFixed(3)}</td><td>${b.n}</td><td>${(100*b.median).toFixed(2)}%</td><td>${(100*b.mean).toFixed(2)}%</td></tr>`).join('')}</tbody></table><h3 style="margin-top:14px">أنظمة هندسية تشخيصية</h3>${regimes.map(r=>`<div class="block"><span class="regimeBadge regime-${r.k}">${diagnosticLabel(r.k)}</span><p>${r.n} حالة · وسيط الخطأ ${Number.isFinite(r.median)?(100*r.median).toFixed(2):'—'}% · المتوسط ${(100*r.mean).toFixed(2)}%</p></div>`).join('')}<div class="block"><p>ارتباطات إضافية: الالتواء ${pearson(skew,err).toFixed(3)} · حصة أكبر محور ${pearson(share,err).toFixed(3)} · البعد الفعّال ${pearson(neff,err).toFixed(3)}.</p></div>`}
